/* generated child CSS: 01-header/header.default/block.css */
/* lab-ui block · header.default
   Depends: 00-tokens/tokens.css + 03-cta/cta.btn-primary-ring/block.css
   + 04-language/language.locale-dropdown/block.css. Light theme.

   Multi-level nav model:
     .nav-item[data-kind="link"]      — plain anchor (no panel)
     .nav-item[data-kind="dropdown"]  — trigger + .nav-panel--list  (single-column)
     .nav-item[data-kind="mega"]      — trigger + .nav-panel--mega  (multi-column)

   Desktop panels open on :hover + :focus-within and on [data-open="true"]
   (the latter is for click/tap toggling via block.js). Below 1024px,
   the burger reveals a full-width menu and nested panel links are shown
   inline instead of as accordions. */

.header-host {
  position: sticky;
  top: 0;
  z-index: 40;
}

.header-host .header--default {
  position: relative;
  top: auto;
}

.header--default {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(var(--backdrop-blur-header, 1.25rem));
  -webkit-backdrop-filter: blur(var(--backdrop-blur-header, 1.25rem));
  border-bottom-left-radius: 2rem;
  border-bottom-right-radius: 2rem;
  box-shadow: 0 18px 46px -34px rgba(27, 29, 37, 0.42);
  transition: background-color var(--transition-duration) ease,
              box-shadow var(--transition-duration) ease;
}

.header--default .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.header--default .header-inner {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 26px;
  min-height: 4.375rem;
  font-family: var(--font-family);
}

.header--default .header-logo {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--color-heading);
  text-decoration: none;
}
.header--default .header-logo svg {
  width: 20px;
  height: 20px;
}
.header--default .header-logo-text {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.018em;
}

/* ─── Nav (unified) ─── */
.header-nav {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  justify-self: center;
}

.nav-item { position: relative; }

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.2s ease, color 0.2s ease;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-family: inherit;
  line-height: 1;
}
.nav-link:hover,
.nav-item:hover > .nav-link,
.nav-item[data-open="true"] > .nav-link {
  background: rgba(27, 29, 37, 0.045);
}

.nav-chev { transition: transform 0.2s ease; }
.nav-item:hover .nav-chev,
.nav-item:focus-within .nav-chev,
.nav-item[data-open="true"] .nav-chev { transform: rotate(180deg); }

/* ─── Panels (shared base) ─── */
.nav-panel {
  position: absolute;
  top: calc(100% + 8px);
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid rgba(27, 29, 37, 0.08);
  border-radius: 18px;
  box-shadow: 0 24px 60px -26px rgba(27, 29, 37, 0.34);
  backdrop-filter: blur(var(--backdrop-blur-panel, 18px));
  -webkit-backdrop-filter: blur(var(--backdrop-blur-panel, 18px));
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: opacity 0.18s ease, transform 0.18s ease;
  z-index: 50;
}

/* Invisible hover-bridge that spans the 8 px gap between the trigger
   and the panel. Without it, mouse moving from trigger down into the
   panel leaves nav-item's bounding box mid-gap, :hover drops, panel
   closes before the mouse arrives. The bridge is a child of .nav-panel
   (so it inherits the parent's pointer-events:auto when the panel is
   open) and extends UP from the panel's top edge by 10 px so it covers
   the visual gap. Stays full panel width so diagonal mouse paths still
   land in it. */
.nav-panel::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 0;
  right: 0;
  height: 10px;
  /* background: rgba(255,0,0,0.15);  ← uncomment to debug */
}

.nav-item:hover > .nav-panel,
.nav-item:focus-within > .nav-panel,
.nav-item[data-open="true"] > .nav-panel {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

/* ─── List panel (dropdown) ─── */
.nav-panel--list {
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  min-width: 220px;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  list-style: none;
  margin: 0;
}
.nav-item:hover > .nav-panel--list,
.nav-item:focus-within > .nav-panel--list,
.nav-item[data-open="true"] > .nav-panel--list {
  transform: translateX(-50%) translateY(0);
}
.nav-list-link {
  display: block;
  padding: 10px 14px;
  border-radius: 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.15s ease;
}
.nav-list-link:hover { background: rgba(27, 29, 37, 0.045); }

/* ─── Mega panel ─── */
.nav-panel--mega {
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  width: max-content;
  max-width: min(680px, 92vw);
  padding: 14px;
  display: grid;
  grid-template-columns: repeat(2, minmax(176px, 1fr));
  gap: 12px 16px;
}
.nav-item:hover > .nav-panel--mega,
.nav-item:focus-within > .nav-panel--mega,
.nav-item[data-open="true"] > .nav-panel--mega {
  transform: translateX(-50%) translateY(0);
}
.nav-mega-col { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.nav-mega-title {
  margin: 0 0 5px;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-blue);
  font-weight: 500;
}
.nav-mega-link {
  display: block;
  padding: 8px 10px;
  border-radius: 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.15s ease;
}
.nav-mega-link:hover { background: rgba(27, 29, 37, 0.045); }

/* Hide empty mega columns / links via block.js (sets [hidden]) */
.nav-panel [hidden] { display: none !important; }

/* ─── Optional Breadcrumb Chip ───
   Breadcrumb is owned by header.default. It hangs from the sticky
   header's bottom edge inside the same page/header host. */
.bc-chip {
  position: absolute;
  top: 4.375rem;
  left: max(
    var(--container-padding-x),
    calc((100vw - (var(--container-width) + var(--container-padding-x) * 2)) / 2 + var(--container-padding-x))
  );
