  );
  backdrop-filter: blur(3.125rem);
  -webkit-backdrop-filter: blur(3.125rem);
  border: 1px solid rgba(0, 0, 0, 0.04);
  border-top: 0;
  box-shadow: 0 6px 16px -12px rgba(0, 0, 0, 0.18);
