    border-radius: 1rem;
    border-top: 1px solid var(--card-border, rgba(0, 0, 0, 0.05));
  }
  .header-actions .locale-list {
    align-items: center;
    padding: 0.35rem;
  }
  .header-actions .locale-item {
    width: 2.25rem;
    height: 2.25rem;
    justify-content: center;
    padding: 0;
    border-radius: 0.75rem;
  }
  .header-actions .locale-item::before {
    content: attr(data-short-code);
    color: var(--color-heading);
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0;
    line-height: 1;
