  .header-actions .locale-item-code {
    display: block;
    color: var(--color-heading);
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0;
    line-height: 1;
  }
  .header-actions .locale-item-label,
  .header-actions .locale-check {
    display: none;
  }
  .burger { display: inline-flex; }
  .header-actions .burger { order: 3; }
  body.is-open .burger span:nth-child(1),
  .header-host.is-open .burger span:nth-child(1) {
    transform: translateY(5.5px) rotate(45deg);
  }
  body.is-open .burger span:nth-child(2),
  .header-host.is-open .burger span:nth-child(2) {
    opacity: 0;
  }
  body.is-open .burger span:nth-child(3),
  .header-host.is-open .burger span:nth-child(3) {
    transform: translateY(-5.5px) rotate(-45deg);
  }
  .burger span { transition: transform 0.18s ease, opacity 0.18s ease; }
}

@media (max-width: 880px) {
  .bc-chip {
    top: 3.125rem;
    left: 50%;
    transform: translateX(-50%);
    gap: 8px;
    height: 30px;
    padding: 0 12px;
    border-radius: 0 0 14px 14px;
    font-size: 11px;
    min-width: 0;
    max-width: calc(100vw - 32px);
