    flex: 0 0 auto;
    font-size: 9px;
  }

  .bc-chip .bc-root {
    flex: 0 1 auto;
    max-width: 26vw;
  }

  .bc-chip [data-mid] {
    flex: 0 2 auto;
    max-width: 22vw;
  }

  .bc-chip .bc-current {
    flex: 1 1 auto;
    max-width: 32vw;
  }

  .bc-chip .bc-link,
  .bc-chip .bc-current {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}

@media (max-width: 600px) {
  .header--default {
    border-bottom-left-radius: 1.5rem;
    border-bottom-right-radius: 1.5rem;
  }
  .header--default .container {
    padding-inline: 1.875rem;
  }
  .header--default .header-inner {
    min-height: 3.125rem;
  }
  .header--default .header-logo {
    gap: 6px;
  }
  .header--default .header-logo svg {
    width: 17px;
    height: 17px;
  }
  .header--default .header-logo-text {
    font-size: 1rem;
  }
  .burger {
    width: 2rem;
    height: 2rem;
    gap: 3.5px;
  }
  .burger span {
    width: 16px;
  }
  .header-nav {
    left: -1.875rem;
    right: -1.875rem;
    gap: 16px;
    max-height: calc(100vh - 3.125rem);
    padding-top: 1.125rem;
    padding-bottom: 1.375rem;
    border-bottom-left-radius: 1.5rem;
    border-bottom-right-radius: 1.5rem;
    clip-path: inset(0 0 100% 0 round 0 0 1.5rem 1.5rem);
  }
  body.is-open .header--default .header-nav,
  .header-host.is-open .header--default .header-nav {
    clip-path: inset(0 0 0 0 round 0 0 1.5rem 1.5rem);
  }
  .nav-link {
    padding: 0;
    font-size: 1rem;
  }
  .header-actions {
    gap: 7px;
  }
  .header-cta {
    height: 2rem;
    padding: 0 0.72rem;
    font-size: 0.75rem;
  }
  .header-cta .btn-star {
    display: none;
