  padding-inline: var(--container-padding-x);
}

.faq-top {
  max-width: 56rem;
  margin: 0 auto clamp(2rem, 4vw, 3.5rem);
  text-align: center;
}
.faq-top .eyebrow {
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  text-transform: uppercase;
  letter-spacing: var(--type-eyebrow-tracking);
  background: var(--cta-secondary-fill, linear-gradient(90deg, #56422D 0%, #494938 100%));
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  margin: 0 0 14px;
}
.faq-title {
  margin: 0 0 14px;
  font-weight: var(--type-h2-weight);
  font-size: var(--type-h2-size);
  line-height: var(--type-h2-leading);
  letter-spacing: var(--type-h2-tracking);
  color: var(--color-heading);
}
.faq-lede {
  margin: 0;
  font-size: var(--type-lead-size);
  line-height: var(--type-lead-leading);
  color: var(--color-text);
}

/* ─── Groups ───────────────────────────────────────────────── */
.faq-groups {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 28px 32px;
}

.faq-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.faq-group-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
}
.faq-group-num {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-gray-blue);
}
.faq-group-title {
  margin: 0;
  font-size: 1.0625rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--color-heading);
}

.faq-group-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* ─── Items ────────────────────────────────────────────────── */
.faq-item {
  border: 1px solid rgba(0, 0, 0, 0.08);
  border-radius: 18px;
  background: var(--color-bg);
  overflow: hidden;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.faq-item[open] {
  border-color: rgba(0, 0, 0, 0.16);
  box-shadow: 0 6px 18px -12px rgba(0, 0, 0, 0.18);
}

.faq-q {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 14px 18px;
  cursor: pointer;
  list-style: none;
  color: var(--color-heading);
  font-size: 0.9375rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  user-select: none;
}
.faq-q::-webkit-details-marker { display: none; }
.faq-q:hover .faq-q-text { color: var(--color-text-accent, #56422D); }
.faq-q:focus-visible {
  outline: 2px solid var(--cta-accent);
  outline-offset: -2px;
  border-radius: 18px;
}

.faq-q-text {
  display: inline-block;
}

.faq-q-toggle {
  width: 26px;
  height: 26px;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  background: rgba(0, 0, 0, 0.04);
  color: var(--color-heading);
  transition: transform 0.25s ease, background 0.2s ease, color 0.2s ease;
}
.faq-item[open] .faq-q-toggle {
  transform: rotate(45deg);
  background: var(--cta-secondary-fill, linear-gradient(90deg, #56422D 0%, #494938 100%));
  color: var(--cta-secondary-color, var(--color-white));
}

.faq-a {
  padding: 0 18px 16px;
  color: var(--color-text);
  font-size: 0.9375rem;
  line-height: 1.55;
}

@media (max-width: 860px) {
  .faq-groups { grid-template-columns: 1fr; gap: 24px; }
}

